import type { PostmortemStatusData } from './postmortem-status-data.js'

export function renderPostmortemStatus(data: PostmortemStatusData, updatedOn: string): string {
  const lines: string[] = [
    '# Postmortem Status',
    '',
    '> Automatically generated by `tools/quality/postmortem-status.ts`',
    `> Updated: ${updatedOn}`,
    '',
    '## Summary',
    '',
    '| Status | Count |',
    '|--------|-------|',
    `| open | ${data.openCount} |`,
    `| closed | ${data.closedCount} |`,
    `| **total** | **${data.entries.length}** |`,
    '',
    '## Details',
    '',
    '| Postmortem | Status | Class | Barrier | Regression |',
    '|------------|--------|-------|---------|------------|'
  ]

  for (const { name, frontMatter } of data.entries) {
    const statusIcon = frontMatter.status === 'closed' ? 'closed' : 'open'
    const barrier = frontMatter.barreira ?? '—'
    const regression = frontMatter.regressao.length > 0 ? `${frontMatter.regressao.length} test(s)` : 'none'
    lines.push(`| ${name} | ${statusIcon} | ${frontMatter.classe} | ${barrier} | ${regression} |`)
  }

  lines.push('')
  lines.push('## Legend')
  lines.push('')
  lines.push('- **open** = bug recorded; the fix, its regression, or the class-level review is still incomplete')
  lines.push('- **closed** = bug fixed with at least one permanent regression test (Bug Response Protocol)')
  lines.push('- **Barrier** = named quality gate that prevents the whole bug class, when one was identified')
  lines.push('- **Regression** = permanent test(s) that validate the fix')
  lines.push('')

  return lines.join('\n')
}
